import React, { useCallback, useEffect, useMemo, useState } from 'react';
import { useDispatch } from 'react-redux';
import {
  Button,
  DEFAULT_CATALOG_LIST_TABLE_CONFIG,
  LIN_ERP_LIST_FILTER_LAYOUT,
  LinCatalogDataGrid,
  LinCatalogHistoryModal,
  LinCatalogListPagination,
  LinCatalogRowActionMenu,
  LinCatalogUiSchemaEditorModal,
  LinErpListFilterBar,
  LinPageLayout,
  Modal,
  SearchInput,
  SearchTextInput,
  Select,
  buildCatalogRowMenuItems,
  catalogListTableConfigFromSchema,
  dispatchAppToast,
  useCatalogHistoryModal,
  useErpListSelection,
  useLinCatalogColumnFilterSort,
  useServerPagedListLoading,
  type ErpListTableConfig,
  type LinCatalogRowMenuItem,
} from '@linm-soft-org/linm-web-common-components';
import { useCatalogUiSchema } from '../../hooks/useCatalogUiSchema';
import { nghiemThuService } from '../../services/nghiemThu/nghiemThuService';
import { nghiemThuListPermissions } from '../../services/nghiemThu/permissions';
import {
  FALLBACK_INIT_DATA,
  statusLabel,
  templateTypeLabel,
  type NghiemThuDto,
  type NghiemThuLookupOption,
} from '../../services/nghiemThu/responseModel';
import { catalogUiSchemaService } from '../../services/catalogUiSchema/catalogUiSchemaService';
import {
  buildDynamicGridColumns,
  type UiListColumnBootstrap,
} from '../../utils/bootstrapCatalogUiSchema';
import {
  ROAD_ROUTE_LOOKUP_CONFIG,
  ROAD_ROUTE_SEED,
  lookupNameOnly,
} from '../../services/attendance/lookups';
import { useInAppNavigate } from '../../router/navigateInAppPath';
import styles from './NghiemThuListPage.module.css';
import { fromCatalogToolbar } from '../buildRmmsGenericToolbar';

const LIST_PATH = '/nghiem-thu';
const TEST_ID = 'rmms-nghiem-thu-list';
const PAGE_ID = 'nghiem-thu';
const CATALOG_KIND = 'nghiem-thu';
const HISTORY_DOC_TYPE = 'nghiem-thu';
const ROW_MENU_HINT_KEY = `${TEST_ID}-row-menu-hint-dismissed`;

export type NghiemThuFormMode = 'create' | 'edit' | 'view' | 'copy';

function formatDateTime(iso: string): string {
  if (!iso) return '—';
  try {
    return new Date(iso).toLocaleString('vi-VN');
  } catch {
    return iso;
  }
}

const NghiemThuListPage: React.FC = () => {
  const dispatch = useDispatch();
  const catalogHistory = useCatalogHistoryModal();
  const navigate = useInAppNavigate();
  const perms = nghiemThuListPermissions();
  const { schema, reload: reloadSchema } = useCatalogUiSchema(CATALOG_KIND);

  const [searchDraft, setSearchDraft] = useState('');
  const [statusDraft, setStatusDraft] = useState('');
  const [routeDraft, setRouteDraft] = useState('');
  const [templateTypeDraft, setTemplateTypeDraft] = useState('');
  const [fromDateDraft, setFromDateDraft] = useState('');
  const [toDateDraft, setToDateDraft] = useState('');
  const [search, setSearch] = useState('');
  const [statusFilter, setStatusFilter] = useState('');
  const [routeFilter, setRouteFilter] = useState('');
  const [templateTypeFilter, setTemplateTypeFilter] = useState('');
  const [fromDate, setFromDate] = useState('');
  const [toDate, setToDate] = useState('');
  const [initStatuses, setInitStatuses] = useState<NghiemThuLookupOption[]>(
    FALLBACK_INIT_DATA.statuses,
  );
  const [initTemplateTypes, setInitTemplateTypes] = useState<NghiemThuLookupOption[]>(
    FALLBACK_INIT_DATA.templateTypes,
  );
  const [page, setPage] = useState(1);
  const [pageSize, setPageSize] = useState<number>(50);
  const [items, setItems] = useState<NghiemThuDto[]>([]);
  const [totalCount, setTotalCount] = useState(0);
  const [rowMenu, setRowMenu] = useState<{
    x: number;
    y: number;
    row: NghiemThuDto;
  } | null>(null);
  const [configOpen, setConfigOpen] = useState(false);
  const [pendingDelete, setPendingDelete] = useState<NghiemThuDto | null>(null);
  const [tableConfig, setTableConfig] = useState<ErpListTableConfig>(() => ({
    ...DEFAULT_CATALOG_LIST_TABLE_CONFIG,
    ...catalogListTableConfigFromSchema(undefined),
    resizable: true,
  }));

  useEffect(() => {
    if (!schema?.list) return;
    setTableConfig({
      ...DEFAULT_CATALOG_LIST_TABLE_CONFIG,
      ...catalogListTableConfigFromSchema(schema.list),
      resizable: true,
    });
  }, [schema]);

  const {
    showTableLoading,
    pageLoading,
    pulseSearch,
    setLoadingMode,
    beginFetch,
    endFetch,
  } = useServerPagedListLoading();

  const {
    columnFilters,
    sortState,
    onColumnFilterConfirm,
    onColumnFilterClear,
    onSortChange,
    processRows,
  } = useLinCatalogColumnFilterSort({
    onResetPage: () => setPage(1),
  });

  const load = useCallback(() => {
    beginFetch();
    nghiemThuService
      .getList({
        search: search.trim() || undefined,
        status: statusFilter || undefined,
        route: routeFilter || undefined,
        templateType: templateTypeFilter || undefined,
        fromDate: fromDate || undefined,
        toDate: toDate || undefined,
        page,
        pageSize,
      })
      .then((res) => {
        setItems(res.items);
        setTotalCount(res.totalCount);
      })
      .catch(() => {
        setItems([]);
        setTotalCount(0);
      })
      .finally(() => endFetch());
  }, [
    search,
    statusFilter,
    routeFilter,
    templateTypeFilter,
    fromDate,
    toDate,
    page,
    pageSize,
    beginFetch,
    endFetch,
  ]);

  useEffect(() => {
    let cancelled = false;
    void nghiemThuService.getInitData().then((data) => {
      if (cancelled || !data) return;
      if (data.statuses?.length) setInitStatuses(data.statuses);
      if (data.templateTypes?.length) setInitTemplateTypes(data.templateTypes);
    });
    return () => {
      cancelled = true;
    };
  }, []);

  useEffect(() => {
    let cancelled = false;
    const t = window.setTimeout(() => {
      if (!cancelled) load();
    }, 0);
    return () => {
      cancelled = true;
      window.clearTimeout(t);
    };
  }, [load]);

  const applyFilters = useCallback(
    (
      nextSearch: string,
      nextStatus: string,
      nextRoute: string,
      nextTemplateType: string,
      nextFrom: string,
      nextTo: string,
    ) => {
      pulseSearch(() => {
        setSearch(nextSearch.trim());
        setStatusFilter(nextStatus);
        setRouteFilter(nextRoute);
        setTemplateTypeFilter(nextTemplateType);
        setFromDate(nextFrom);
        setToDate(nextTo);
        setPage(1);
      });
    },
    [pulseSearch],
  );

  const handleSearchClick = useCallback(() => {
    applyFilters(
      searchDraft,
      statusDraft,
      routeDraft,
      templateTypeDraft,
      fromDateDraft,
      toDateDraft,
    );
  }, [
    applyFilters,
    searchDraft,
    statusDraft,
    routeDraft,
    templateTypeDraft,
    fromDateDraft,
    toDateDraft,
  ]);

  useEffect(() => {
    const t = window.setTimeout(() => {
      applyFilters(
        searchDraft,
        statusDraft,
        routeDraft,
        templateTypeDraft,
        fromDateDraft,
        toDateDraft,
      );
    }, 300);
    return () => window.clearTimeout(t);
    // eslint-disable-next-line react-hooks/exhaustive-deps -- only re-filter when draft inputs change
  }, [searchDraft, statusDraft, routeDraft, templateTypeDraft, fromDateDraft, toDateDraft]);

  const handleDateRangeChange = useCallback((from?: string, to?: string) => {
    setFromDateDraft(from ?? '');
    setToDateDraft(to ?? '');
  }, []);

  const statusOptions = useMemo(
    () => [
      { value: '', label: 'Tất cả' },
      ...initStatuses.map((t) => ({
        value: t.value,
        label: t.label || statusLabel(t.value, initStatuses),
      })),
    ],
    [initStatuses],
  );

  const templateTypeOptions = useMemo(
    () => [
      { value: '', label: 'Tất cả' },
      ...initTemplateTypes.map((t) => ({
        value: t.value,
        label: t.label || templateTypeLabel(t.value, initTemplateTypes),
      })),
    ],
    [initTemplateTypes],
  );

  const openCreate = useCallback(() => {
    if (!perms.canCreate) return;
    navigate(`${LIST_PATH}/new`);
  }, [perms.canCreate, navigate]);

  const reloadAll = useCallback(() => {
    setLoadingMode('filter');
    load();
  }, [load, setLoadingMode]);

  const handlePageChange = useCallback((next: number) => {
    setPage(next);
  }, []);

  const handlePageSizeChange = useCallback((next: number) => {
    setPageSize(next);
    setPage(1);
  }, []);

  const uiColumns = useMemo<UiListColumnBootstrap<NghiemThuDto>[]>(
    () => [
      {
        key: 'code',
        label: 'Mã',
        width: '120px',
        control: 'TEXT',
        allowSort: true,
        render: (row) => (
          <button
            type="button"
            className={styles.codeLink}
            onClick={() => {
              navigate(`${LIST_PATH}/${encodeURIComponent(row.id)}`);
            }}
            data-testid={`${TEST_ID}-code-${row.code}`}
          >
            {row.code}
          </button>
        ),
        getDisplayValue: (r) => r.code,
      },
      {
        key: 'status',
        label: 'Trạng thái',
        width: '110px',
        control: 'SELECT',
        allowSort: true,
        render: (row) => statusLabel(row.status, initStatuses),
        getDisplayValue: (r) => statusLabel(r.status, initStatuses),
      },
      {
        key: 'route',
        label: 'Tuyến đường',
        width: '160px',
        control: 'TEXT',
        allowSort: true,
        render: (row) => row.route || '—',
        getDisplayValue: (r) => r.route,
      },
      {
        key: 'templateType',
        label: 'Mẫu NT',
        width: '140px',
        control: 'SELECT',
        allowSort: true,
        render: (row) => templateTypeLabel(row.templateType, initTemplateTypes),
        getDisplayValue: (r) => templateTypeLabel(r.templateType, initTemplateTypes),
      },
      {
        key: 'assigneeCode',
        label: 'Cán bộ NT',
        width: '120px',
        control: 'TEXT',
        allowSort: true,
        render: (row) => row.assigneeCode || '—',
        getDisplayValue: (r) => r.assigneeCode,
      },
      {
        key: 'inspectedAt',
        label: 'Ngày NT',
        width: '150px',
        control: 'DATE',
        allowSort: true,
        render: (row) => formatDateTime(row.inspectedAt),
        getDisplayValue: (r) => r.inspectedAt,
      },
      {
        key: 'updatedAt',
        label: 'Cập nhật',
        width: '150px',
        control: 'DATE',
        allowSort: true,
        render: (row) => formatDateTime(row.updatedAt),
        getDisplayValue: (r) => r.updatedAt,
      },
    ],
    [navigate, initStatuses, initTemplateTypes],
  );

  const gridColumns = useMemo(
    () => buildDynamicGridColumns(schema, uiColumns),
    [schema, uiColumns],
  );

  const tableRows = useMemo(
    () => processRows(items, gridColumns),
    [processRows, items, gridColumns],
  );

  const listSelection = useErpListSelection<NghiemThuDto>({
    rows: tableRows,
    totalCount,
    page,
    pageSize,
    getRowId: (r) => r.id,
  });
  const { activeRow, selectActiveRow, clearSelection } = listSelection;

  const openRow = useCallback(
    (row: NghiemThuDto, mode: NghiemThuFormMode) => {
      selectActiveRow(row);
      let next = mode;
      if (mode === 'edit' && !perms.canUpdate) next = 'view';
      if (mode === 'copy' && !perms.canCreate) next = 'view';
      if (next === 'edit') {
        navigate(`${LIST_PATH}/${encodeURIComponent(row.id)}?mode=edit`);
      } else if (next === 'copy') {
        navigate(`${LIST_PATH}/new?copyFrom=${encodeURIComponent(row.id)}`);
      } else if (next === 'create') {
        navigate(`${LIST_PATH}/new`);
      } else {
        navigate(`${LIST_PATH}/${encodeURIComponent(row.id)}`);
      }
    },
    [selectActiveRow, perms.canUpdate, perms.canCreate, navigate],
  );

  const handleHistoryToolbar = useCallback(() => {
    if (!activeRow) {
      dispatchAppToast(dispatch, {
        message: 'Chọn một dòng (menu dòng) rồi mở Lịch sử.',
        type: 'info',
      });
      return;
    }
    catalogHistory.openHistory({
      documentType: HISTORY_DOC_TYPE,
      documentId: activeRow.id,
      documentCode: activeRow.code,
    });
  }, [activeRow, catalogHistory.openHistory, dispatch]);

  const openConfig = useCallback(() => {
    setConfigOpen(true);
  }, []);

  const requestDelete = useCallback(
    (row: NghiemThuDto) => {
      if (!perms.canDelete) {
        dispatchAppToast(dispatch, {
          message: 'Không có quyền xóa nghiệm thu.',
          type: 'warning',
        });
        return;
      }
      setPendingDelete(row);
    },
    [perms.canDelete, dispatch],
  );

  const confirmDelete = useCallback(async () => {
    const row = pendingDelete;
    if (!row) return;
    setPendingDelete(null);
    try {
      await nghiemThuService.delete(row.id);
      dispatchAppToast(dispatch, {
        message: `Đã xóa nghiệm thu ${row.code}`,
        type: 'success',
      });
      clearSelection();
      setLoadingMode('filter');
      load();
    } catch (err) {
      dispatchAppToast(dispatch, {
        message: err instanceof Error ? err.message : 'Xóa nghiệm thu thất bại.',
        type: 'error',
      });
    }
  }, [pendingDelete, dispatch, clearSelection, setLoadingMode, load]);

  const catalogToolbar = useMemo(
    () => ({
      testIdPrefix: TEST_ID,
      onRefresh: reloadAll,
      canAdd: perms.canCreate,
      onAdd: openCreate,
      canHistory: true,
      onHistory: handleHistoryToolbar,
      showSchemaConfig: true,
      onEditConfig: openConfig,
      showEdit: Boolean(activeRow && perms.canUpdate),
      showView: Boolean(activeRow && perms.canRead),
      onEdit: activeRow ? () => openRow(activeRow, 'edit') : undefined,
      onView: activeRow ? () => openRow(activeRow, 'view') : undefined,
      canDelete: Boolean(activeRow && perms.canDelete),
      onDelete: activeRow
        ? () => {
            requestDelete(activeRow);
          }
        : undefined,
    }),
    [
      reloadAll,
      perms.canCreate,
      perms.canUpdate,
      perms.canRead,
      perms.canDelete,
      openCreate,
      handleHistoryToolbar,
      openConfig,
      activeRow,
      openRow,
      requestDelete,
    ],
  );

  const listFilters = useMemo(
    () => (
      <LinErpListFilterBar
        testIdPrefix={TEST_ID}
        fromDate={fromDateDraft}
        toDate={toDateDraft}
        onDateChange={handleDateRangeChange}
        onSearch={handleSearchClick}
        searchAriaLabel="Tìm"
        loading={showTableLoading}
        leading={(
          <>
            <div data-testid={`${TEST_ID}-field-search`}>
              <SearchTextInput
                label="Tìm kiếm"
                placeholder="Mã / tuyến / cán bộ…"
                value={searchDraft}
                onChange={setSearchDraft}
                testId={`${TEST_ID}-search-text`}
              />
            </div>
            <div data-testid={`${TEST_ID}-field-status`}>
              <Select
                label="Trạng thái"
                options={statusOptions}
                value={statusDraft}
                onChange={(e) => setStatusDraft(String(e.target.value))}
                data-testid={`${TEST_ID}-status-filter`}
                fullWidth
                size="small"
              />
            </div>
            <div data-testid={`${TEST_ID}-field-route`}>
              <SearchInput
                label="Tuyến đường"
                config={ROAD_ROUTE_LOOKUP_CONFIG}
                value={routeDraft}
                primaryDisplay={lookupNameOnly(ROAD_ROUTE_SEED, routeDraft)}
                showSecondaryInput={false}
                placeholder="Tất cả tuyến"
                onChange={(item) => setRouteDraft(item.value)}
                onClear={() => setRouteDraft('')}
              />
            </div>
            <div data-testid={`${TEST_ID}-field-templateType`}>
              <Select
                label="Mẫu NT"
                options={templateTypeOptions}
                value={templateTypeDraft}
                onChange={(e) => setTemplateTypeDraft(String(e.target.value))}
                data-testid={`${TEST_ID}-templateType-filter`}
                fullWidth
                size="small"
              />
            </div>
          </>
        )}
      />
    ),
    [
      searchDraft,
      statusDraft,
      routeDraft,
      templateTypeDraft,
      fromDateDraft,
      toDateDraft,
      handleSearchClick,
      handleDateRangeChange,
      statusOptions,
      templateTypeOptions,
      showTableLoading,
    ],
  );

  const rowMenuItems = useMemo<LinCatalogRowMenuItem[]>(
    () =>
      buildCatalogRowMenuItems({
        showView: perms.canRead,
        showEdit: perms.canUpdate,
        showCopy: perms.canCreate,
        showDelete: perms.canDelete,
        showHistory: perms.canRead,
      }),
    [perms.canRead, perms.canUpdate, perms.canCreate, perms.canDelete],
  );

  const handleRowMenuSelect = useCallback(
    (action: string) => {
      const row = rowMenu?.row;
      setRowMenu(null);
      if (!row) return;
      switch (action) {
        case 'view':
          openRow(row, 'view');
          break;
        case 'edit':
          openRow(row, 'edit');
          break;
        case 'copy':
          openRow(row, 'copy');
          break;
        case 'delete':
          requestDelete(row);
          break;
        case 'history':
          catalogHistory.openHistory({
            documentType: HISTORY_DOC_TYPE,
            documentId: row.id,
            documentCode: row.code,
          });
          break;
        default:
          break;
      }
    },
    [rowMenu?.row, openRow, requestDelete, catalogHistory.openHistory],
  );

  const emptyMessage =
    search.trim() ||
    statusFilter ||
    routeFilter ||
    templateTypeFilter ||
    fromDate ||
    toDate
      ? 'Không có nghiệm thu phù hợp bộ lọc.'
      : 'Không có dữ liệu nghiệm thu.';

  return (
    <div
      className={styles.page}
      data-catalog-list-page
      data-lin-list-layout="erp-filter-bar"
      data-testid={`${TEST_ID}-page`}
    >
      <LinPageLayout
        kind="catalog"
        listLayoutVariant="erp-filter-bar"
        listHeaderClassName={LIN_ERP_LIST_FILTER_LAYOUT.header}
        listFiltersClassName={LIN_ERP_LIST_FILTER_LAYOUT.filtersHost}
        testIdPrefix={TEST_ID}
        pageId={PAGE_ID}
        header={{
          title: 'Nghiệm thu',
          titleIconClass: 'fas fa-clipboard-check',
          pageId: PAGE_ID,
        }}
        toolbar={fromCatalogToolbar(catalogToolbar)}
        listTitle="Danh sách nghiệm thu"
        listRowMenuHelp
        filters={listFilters}
        filtersTestId={`${TEST_ID}-filters`}
        showTableLoading={showTableLoading}
        pageLoading={pageLoading}
        skeletonRows={8}
        footer={
          <LinCatalogListPagination
            testIdPrefix={TEST_ID}
            page={page}
            pageSize={pageSize}
            totalCount={totalCount}
            onPageChange={handlePageChange}
            onPageSizeChange={handlePageSizeChange}
          />
        }
        modals={
          <>
            <LinCatalogRowActionMenu
              open={rowMenu != null}
              x={rowMenu?.x ?? 0}
              y={rowMenu?.y ?? 0}
              testIdPrefix={TEST_ID}
              onClose={() => setRowMenu(null)}
              onSelect={(action) => {
                handleRowMenuSelect(action);
              }}
              items={rowMenuItems}
            />
            <LinCatalogUiSchemaEditorModal
              isOpen={configOpen}
              onClose={() => setConfigOpen(false)}
              testIdPrefix={TEST_ID}
              catalogKind={CATALOG_KIND}
              loadSchema={catalogUiSchemaService.get}
              saveSchema={catalogUiSchemaService.save}
              onSaved={(next) => {
                setTableConfig({
                  ...DEFAULT_CATALOG_LIST_TABLE_CONFIG,
                  ...catalogListTableConfigFromSchema(next.list),
                  resizable: true,
                });
                reloadSchema();
                setConfigOpen(false);
              }}
              onError={(message) =>
                dispatchAppToast(dispatch, { message, type: 'error' })
              }
              onSuccess={(message) =>
                dispatchAppToast(dispatch, { message, type: 'success' })
              }
            />
            {catalogHistory.modalProps ? (
              <LinCatalogHistoryModal
                {...catalogHistory.modalProps}
                testIdPrefix={TEST_ID}
                onError={(message) =>
                  dispatchAppToast(dispatch, { message, type: 'error' })
                }
              />
            ) : null}
            <Modal
              isOpen={pendingDelete != null}
              onClose={() => setPendingDelete(null)}
              title="Xóa nghiệm thu"
              size="sm"
              stacked
            >
              <p>
                Xóa nghiệm thu «{pendingDelete?.code}»? Thao tác ẩn bản ghi (soft delete).
              </p>
              <div style={{ display: 'flex', gap: 8, justifyContent: 'flex-end', marginTop: 16 }}>
                <Button
                  type="button"
                  variant="secondary"
                  size="sm"
                  onClick={() => setPendingDelete(null)}
                  data-testid={`${TEST_ID}-delete-cancel`}
                >
                  Hủy
                </Button>
                <Button
                  type="button"
                  variant="primary"
                  size="sm"
                  onClick={() => void confirmDelete()}
                  data-testid={`${TEST_ID}-confirm-delete`}
                >
                  Xóa
                </Button>
              </div>
            </Modal>
          </>
        }
      >
        <div className={styles.gridWrap} data-testid={`${TEST_ID}-grid-wrap`}>
          <LinCatalogDataGrid
            testIdPrefix={TEST_ID}
            rows={tableRows}
            page={page}
            pageSize={pageSize}
            columns={gridColumns}
            getRowId={(r) => r.id}
            selection={listSelection}
            tableConfig={tableConfig}
            filterSourceRows={items}
            paginateClient={false}
            columnFilters={columnFilters}
            onColumnFilterConfirm={onColumnFilterConfirm}
            onColumnFilterClear={onColumnFilterClear}
            sortState={sortState}
            onSortChange={onSortChange}
            empty={
              <div className={styles.empty} data-testid={`${TEST_ID}-empty`}>
                {emptyMessage}
              </div>
            }
            onRowOpenActionMenu={({ row, x, y }) => {
              selectActiveRow(row);
              setRowMenu({ row, x, y });
            }}
            onRowDoubleClick={(row) => openRow(row, 'view')}
            rowMenuHintDismissStorageKey={ROW_MENU_HINT_KEY}
          />
        </div>
      </LinPageLayout>
    </div>
  );
};

export default NghiemThuListPage;
