import type { CatalogUiField, CatalogUiSchema } from '@linm-soft-org/linm-web-common-components';

/** List-surface visible fields ordered by schema (display mode). */
export function listVisibleFields(
  schema: CatalogUiSchema | null | undefined,
): CatalogUiField[] {
  if (!schema?.fields?.length) return [];
  return schema.fields
    .filter((f) => f.list?.visible === true)
    .sort((a, b) => (a.list?.order ?? 999) - (b.list?.order ?? 999));
}
